import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int M = sc.nextInt();

        List<List<Integer>> D = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            D.add(new ArrayList<>());
        }

        for (int d = 2; d <= n; d++) {
            for (int dst = 2 * d; dst <= n; dst += d) {
                D.get(dst).add(d);
            }
        }

        long[] F = new long[n + 1];
        F[1] = 1;
        if (n >= 2) {
            F[2] = 2;
        }
        for (int x = 3; x <= n; x++) {
            F[x] = (2 * F[x - 1] + F[x / (x - 1)]) % M;
            long S = 0;
            for (int d : D.get(x)) {
                if (d >= 2 && d <= x - 2) {
                    S += F[x / d] - F[(x - 1) / d];
                }
            }
            F[x] = (F[x] + S) % M;
        }

        System.out.println(F[n] % M);
        sc.close();
    }
}
